// The form gives ONE item containing several files.
// We turn it into ONE item PER file.
const out = [];

for (const item of $input.all()) {
  for (const key of Object.keys(item.binary || {})) {
    const file = item.binary[key];
    const ext = file.fileName.split('.').pop().toLowerCase();

    out.push({
      json: { fileName: file.fileName, ext: ext },
      binary: { file: file }
    });
  }
}

return out;

// Compression only accepts files named .zip, and a .docx IS a zip inside.
// So we keep the same file but relabel it as zip.
return $input.all().map(item => {
  const file = {
    ...item.binary.file,
    fileName: item.json.fileName + '.zip',
    fileExtension: 'zip',
    mimeType: 'application/zip'
  };
  return { json: item.json, binary: { file: file } };
});

// Find word/document.xml inside the unzipped files and turn it into plain text.
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary || {};
  const key = Object.keys(bin).find(k => (bin[k].fileName || '').endsWith('document.xml'));

  let text = '';
  if (key) {
    const xml = (await this.helpers.getBinaryDataBuffer(i, key)).toString('utf8');
    text = xml
      .replace(/<\/w:p>/g, '\n')      // end of paragraph -> new line
      .replace(/<w:br\/>/g, '\n')     // line break inside a cell -> new line
      .replace(/<w:tab\/>/g, ' ')     // tab -> space
      .replace(/<[^>]+>/g, '')        // remove every other tag
      .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  const original = $('Switch').itemMatching(i).json;
  out.push({ json: { fileName: original.fileName, ext: 'docx', text: text } });
}

return out;

// Turn Gemini's reply into one clean candidate record.
// If anything went wrong, the CV is marked unreadable so it gets flagged, never skipped.
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const reply = items[i].json;
  const fileName = $('Build AI request').itemMatching(i).json.fileName;

  let facts = null;
  let problem = '';
  try {
    if (reply.error) throw new Error(typeof reply.error === 'string' ? reply.error : (reply.error.description || reply.error.message || 'API error'));
    if (reply.status && reply.status !== 'completed') throw new Error('Gemini did not finish: ' + reply.status);
    // The answer is the text inside the last "model_output" step.
    const steps = reply.steps || [];
    const output = steps.filter(s => s.type === 'model_output').pop() || steps[steps.length - 1];
    const textPart = ((output && output.content) || []).find(c => c.type === 'text');
    facts = JSON.parse(textPart ? textPart.text : reply.output_text);
  } catch (e) {
    problem = e.message;
  }

  if (!facts) {
    facts = { readable: false, unreadable_reason: 'Could not process: ' + problem };
  }
  if (facts.readable && !facts.email) {
    facts.readable = false;
    facts.unreadable_reason = 'No email address found, so the candidate cannot be identified';
  }

  out.push({ json: { fileName: fileName, ...facts } });
}

return out;

// Build one Gemini request per CV.
// Word files arrive with their text already extracted; PDFs arrive as files,
// which Gemini reads directly (it reads page images, so scanned PDFs work too).
const today = new Date().toISOString().slice(0, 7); // e.g. "2026-10"

const instructions = `You extract facts from one CV for a recruiting database. Today is ${today}.

Rules:
- Only use what the CV says. Never invent. Use "" for unknown text and [] for unknown lists.
- readable: false if the document is blank, not a CV, or too damaged to read. Explain why in unreadable_reason.
- email: lowercase. languages: lowercase English names, e.g. "arabic".
- skills: one entry per skill with years of hands-on experience, summed over the jobs where it was used.
  A job ending in "Present" counts until today.
  Overlapping jobs count once. Round to 1 decimal. A skill only listed (no dated job) gets years 0.
  A tool's years come ONLY from the jobs whose description names that tool. Never copy years from one skill to another.
- The kind of work is a skill too, not only the tools. Every job in a medical office, clinic, telehealth or
  healthcare practice doing admin work (scheduling, patient records, intake, billing, insurance, medical VA)
  counts toward medical_admin. Every customer-facing phone or chat job counts toward phone_support or chat_support.
- Certificates and trainings are skills: any HIPAA training/certificate/compliance means a hipaa entry
  (years = the medical jobs where it applied, or 0 if only the certificate is listed).
- Use these skill names when they apply: gohighlevel, zapier, n8n, make, api_webhooks, hubspot,
  clickfunnels, activecampaign, meta_ads, google_ads, ga4, klaviyo, tiktok_ads, seo,
  phone_support, chat_support, zendesk, freshdesk, intercom, healthcare, medical_admin, hipaa,
  athenahealth, eclinicalworks, epic, insurance_verification, prior_auth,
  quickbooks_online, xero, sage, bank_reconciliations, us_clients, uk_clients.
  Other skills: short lowercase snake_case names.
- cv_updated: the CV's own "last updated" date as YYYY-MM, or "" if it has none.
- cv_text: the full CV as plain text, so it can be searched.`;

const schema = {
  type: 'object',
  properties: {
    readable: { type: 'boolean' },
    unreadable_reason: { type: 'string' },
    full_name: { type: 'string' },
    email: { type: 'string' },
    phone: { type: 'string' },
    location: { type: 'string' },
    headline: { type: 'string' },
    summary: { type: 'string' },
    cv_updated: { type: 'string' },
    languages: { type: 'array', items: { type: 'string' } },
    skills: {
      type: 'array',
      items: {
        type: 'object',
        properties: { skill: { type: 'string' }, years: { type: 'number' } },
        required: ['skill', 'years'],
        additionalProperties: false
      }
    },
    cv_text: { type: 'string' }
  },
  required: ['readable', 'unreadable_reason', 'full_name', 'email', 'phone', 'location',
             'headline', 'summary', 'cv_updated', 'languages', 'skills', 'cv_text'],
  additionalProperties: false
};

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let cvPart;

  if (item.json.ext === 'docx') {
    cvPart = { type: 'text', text: 'CV file: ' + item.json.fileName + '\n\n' + (item.json.text || '(empty document)') };
  } else {
    const pdf = await this.helpers.getBinaryDataBuffer(i, 'file');
    cvPart = { type: 'document', mime_type: 'application/pdf', data: pdf.toString('base64') };
  }

  out.push({
    json: {
      fileName: item.json.fileName,
      body: {
        model: 'gemini-3.5-flash-lite',
        system_instruction: instructions,
        input: [cvPart, { type: 'text', text: 'Extract the facts from this CV.' }],
        response_format: { type: 'text', mime_type: 'application/json', schema: schema }
      }
    }
  });
}

return out;
